{"packet_id":"D032-04","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken initial rental decontrol upon vacancy by bona fide condo/co-op owner-occupant","requirement":"When a bona fide condo/co-op owner-occupant who occupied the unit as principal residence for the previous two years vacates and offers it for rental, the unit is decontrolled solely to set the initial rent at the amount charged in the first lease after vacancy; it is otherwise fully subject to Chapter 155.","key_value":"initial rent = amount charged in first lease after vacancy","coverage_conditions":"Condo/co-op units whose owner continuously occupied the unit as principal residence for the previous two years; unit otherwise fully subject to Chapter 155.","applicability":{"conditions":[{"type":"owner","role":"covered","who":"bona fide condo/co-op owner-occupant of 2 years","unit_limit":null}],"per_tenancy":"Decontrol applies only on vacancy by a bona fide CCOO and only for establishing the initial rent.","coverage_quotes":["In the event that an owner of a condo/co-op unit has continuously occupied said unit as his/her principal residence for the previous two years, the owner may file an affidavit with, and on the form provided by, the Rent Regulation Officer documenting his/her use.","In the event that an individual who qualifies as a bona fide CCOO vacates his/her condo/co-op unit and offers it for rental, said unit is decontrolled solely for the purpose of establishing the initial rent subsequent to the bona fide CCOO vacating."]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Hoboken, N.J., Code § 155-37","quoted_span":"In the event that an individual who qualifies as a bona fide CCOO vacates his/her condo/co-op unit and offers it for rental, said unit is decontrolled solely for the purpose of establishing the initial rent subsequent to the bona fide CCOO vacating.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D032-04","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken COVID-19 temporary moratorium on rent increases","requirement":"During the COVID-19 pandemic state of emergency, rent and other charges (including surcharges and charges for parking, pets, furniture and deposits) may not be increased for property covered by Chapter 155; the moratorium is retroactive to April 1, 2020 and remains in effect until May 7, 2022.","key_value":"no rent increase 2020-04-01 through 2022-05-07","coverage_conditions":"Any property covered by Chapter 155 of the Hoboken Code (rent leveling and stabilization).","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":["A moratorium shall be in effect to prevent any increase in the amount paid in rent or any additional charges whatsoever by tenants covered by this chapter."]},"exemptions":null,"penalty":null,"effective_date":"2020-04-01","valid_through":"2022-05-07","citation":"Hoboken, N.J., Code § 155-38","quoted_span":"The moratorium shall be made retroactive to April 1, 2020, and shall remain in effect until May 7, 2022.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
